// th14_s7_b14 — TH14 v1.00b Extra / st07bs.ecl BossCard7（spellEx 116）
// 卡帧 0 起计时；卡帧 120 = 源 BossCard7 入口 t=0（1892 timerReset）。源时限 3000（1906）。
// 源→目标对应写在相关语句旁；已批准的省略：章节/掉落/纯表现/出生动画/段外交接。

const TIME_LIMIT: int = 3424;       // 120 缓冲 + 3000 源时限 + 300 尾弹 + 4 启动余量
const OPENING_BUFFER: int = 120;
const SOURCE_LIMIT: int = 3000;     // 源 1906 setInterrupt(0,0,50*60,"Boss8")

// TH14 词表（touhou-bullets.ecl）：源 type5 → TH14_BALL2，源 type8 → TH14_RICE
const TH14_BALL2: int = 432;
const TH14_RICE: int = 480;
const BOSS_LASER_COLOR: int = 6;    // 源 2705 etSprite(0,18,6) 的 color 6

// TaikoA07_at2 的出生 EX：ANIM(省略) + VELTIME a=320 r=2.0 s=-999999（保持当前角）
// @N 是后置延迟：先执行本 op，再等 N 帧才轮到下一条。
xformdef RAMP_320 {
    @320 set_accel(0.00625fx);      // (2.0-0)/320，持续 320 帧
    set_accel(0fx);
}

// TaikoDead7 的出生 EX：ANIM(省略) + WAIT 60 + VELTIME a=120 r=目标速 s=-999999
xformdef D7_RAMP(delta: fx) {
    @60 add_speed(0fx);             // 源 WAIT 60：先等 60 帧
    @120 set_accel(delta);          // (目标标量速-当前层速)/120，持续 120 帧
    set_accel(0fx);
}

sub main() {
    _ = spawn_enemy(0fx, 128fx, 3500, 0, 0, 0, boss_main);   // 源 Boss 0017 movePos(0,128)
    loop { wait(600); }
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);               // 源 Boss 0028 setHitbox(48,48) 普通圆 r=24
    set_hurtbox(24fx);              // 源 Boss 0027 setHurtbox(48,48)
    spell_begin(0, 116, pattern, TIME_LIMIT, 500000, 0, 0);  // 1907 spellEx(116,3000,500000)
    wait_spell();
    loop { wait(1); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);   // 1908 movePosTime(60,4,0,144)；1909 限位见助手
    wait(60);                                 // t=60：1911-1917 蓄力/音效表现省略
    wait(90);                                 // t=150
    spawn card7_at();                         // 1922 @BossCard7_at() async
    wait(180);                                // 1923 wait(180) → t=330
    var t: int = 330;
    while t < SOURCE_LIMIT {                  // 源 3000 超时后不再移动（Boss8 不启动）
        card_move_rand();                     // 1926 moveRand(60,0,0.6)
        card_wait(180);                       // 1927 wait(180)
        t = t + 180;
    }
    loop { wait(1000); }
}

// 1933-1998 BossCard7_at：24 只子敌编队，周期 600 帧；第 5 周期在源 3000 截断
async sub card7_at() {
    for c in 0..5 {
        spawn_group(180deg, 20deg);                 // 1939-1951 F0=π 起，每只 +0.349066(20°)
        wait(120);                                  // 1952
        spawn_a07b_pair((0 - 4096) as angle, (0 - 28672) as angle);   // 1953-1966 F0=-22.5°/-157.5°
        spawn_group(0deg, -20deg);                  // 1967-1979 F0=0 起，每只 -20°
        if c < 4 {                                  // 源 t=3080/3140 的两只被 3000 超时截断
            wait(120);                              // 1980
            spawn_a07b_pair((0 - 28672) as angle, (0 - 4096) as angle);   // 1981-1994
        }
    }
}

sub spawn_group(first: angle, step: angle) {
    var f0: angle = first;
    for i in 0..10 {
        // 1946 enmCreate("TaikoA07",0,0,100,10,0)：父 FINAL 上出生
        _ = spawn_enemy($self_x, $self_y, 100, 0, 10, 0, taiko07(f0));
        f0 = f0 + step;                             // 1948
        wait(10);                                   // 1949
    }
}

sub spawn_a07b_pair(first: angle, second: angle) {
    // 1956/1963：F2 = (π/2-120*1°) + RANDF2*0.17453292；RANDF2∈[-1,1)
    var r: int = rand(65536) - 32768;
    _ = spawn_enemy($self_x, $self_y, 100, 0, 10, 0, taiko07b(first, -30deg + ((r / 18) as angle)));
    wait(60);                                       // 1958
    r = rand(65536) - 32768;
    _ = spawn_enemy($self_x, $self_y, 100, 0, 10, 0, taiko07b(second, -30deg + ((r / 18) as angle)));
    wait(20);                                       // 1966
}

// 2663-2700 TaikoA07：F1=3，A=F2+120*F3，尾部激光随敌每帧走
async sub taiko07(f0: angle) {
    set_invuln(65535);
    set_hitbox(16fx);                               // 2669 setHitbox(32,40) 普通圆 r=16
    set_hurtbox(16fx);                              // 2670 setHurtbox(32,48)
    move_vel(0, f0, 3fx, EASE_LINEAR);              // 2675 moveVel(F0, 3)
    move_speed(120, 0fx, EASE_LINEAR);              // 2676 moveSpeedTime(120,0,0)
    wait(120);                                      // 2681-2688 120 帧旋转（表现/圆框旋转省略）
    var a: angle = -30deg + 120deg;                 // %A=F2+120*F3；F3=1°，F2=π/2-120*1°
    move_vel(0, a, 0fx, EASE_LINEAR);               // 2689 moveVel(A, 0)
    move_speed(60, 8fx, EASE_BACK_IN_P25);          // 2690 moveSpeedTime(60,22,8) mode22=BACK(0.25)
    wait(1);                                        // 2691 @TaikoA07_at 次帧首跑
    // 2704-2711：laserNew(0,0,600,0,48) + laserTiming(0,16,40,180,20,0)
    // Infinite 判定段 0.9L=540，w=48≥32 时半高 (w-8)/3=13.333 → 全宽 26.6667
    // 三段：warn=16；active=expand+hold=41+180=221；fade=20（扩张期按恒宽近似）
    var lz: int = laser(BOSS_LASER_COLOR, $self_x, $self_y, a + 180deg,
                        540fx, 26.6667fx, 16, 221, 20);
    lz_anchor(lz, $self_enemy, 0fx, 0fx);           // 2714 laserOffset($I0,FINAL_X,FINAL_Y)
    wait(200);                                      // 2692
    loop { wait(1000); }                            // 2693-2698 flagClear(12) 后常驻
}

// 2784-2821 TaikoA07b + 2721-2764 TaikoA07_at2 + 2858-2882 TaikoDead7
async sub taiko07b(f0: angle, f2: angle) {
    set_invuln(65535);
    set_hitbox(16fx);
    set_hurtbox(16fx);
    move_vel(0, f0, 2fx, EASE_LINEAR);              // 2796 moveVel(F0, 2)
    move_speed(120, 0fx, EASE_LINEAR);              // 2797 moveSpeedTime(120,0,0)
    wait(120);                                      // 2802-2809 旋转（表现省略）
    var a: angle = f2 + 120deg;                     // %A=F2+120*F3
    move_vel(0, a, 0fx, EASE_LINEAR);               // 2810
    move_speed(60, 8fx, EASE_BACK_IN_P25);          // 2811 moveSpeedTime(60,22,8)
    wait(1);                                        // 2812 @TaikoA07_at2 次帧首跑
    var lz: int = laser(BOSS_LASER_COLOR, $self_x, $self_y, a + 180deg,
                        540fx, 26.6667fx, 16, 221, 20);
    lz_anchor(lz, $self_enemy, 0fx, 0fx);           // 2734 laserOffset 每帧
    while $self_y < 430fx && $self_x >= -180fx && $self_x <= 180fx { wait(1); }
    if lz_alive(lz) == 1 { lz_cancel(lz); }         // 2742 laserStEnd($I0)
    move_speed(0, 0fx, EASE_LINEAR);                // 2743 moveSpeed(0)
    // 2747-2761：60 帧、每帧一颗；RANDRAD 方向，A+π+RANDF2*5° 方向、半径 0..590 出生
    var b: fx = 0fx;
    for c in 0..60 {
        var ang: angle = (rand(65536)) as angle;                    // %RANDRAD
        var rb: int = rand(65536) - 32768;                         // %RANDF2
        var ob: angle = (a + 180deg) + ((rb / 36) as angle);       // ±5°
        _ = fire(TH14_BALL2, 2, $self_x + b * cos(ob), $self_y + b * sin(ob),
                 0fx, ang, RAMP_320, none);                          // 2752-2757
        b = b + 10fx;                                              // 2758
        wait(1);
    }
    // 2858-2882 TaikoDead7：同帧 5 波，mode10 固定交替层环 N=11 M=5，alpha=RANDRAD，δ=2°
    sh_reset(0);
    sh_sprite(0, TH14_RICE, 2);                     // 2864 etSprite(0,8,2)
    sh_ring(0, 1);                                  // mode10 每层为整环，方向按层镜像
    sh_aim(0, 0);
    sh_count(0, 11, 1);
    var alpha: int = rand(65536);                   // 2871 %RANDRAD
    for v in 0..5 {                                 // 2872-2879：同帧 5 波，各波 etExSet 换 %A
        var target: fx = 1fx + 0.6fx * (v as fx);   // 2875/2876：%A=1.0 起每次 +0.6
        for q in 0..5 {                             // 2865 etCount(0,11,5)：层
            var kk: int = ((q + 1) / 2) * 2;        // k=(q+M%2)&~1 → 0,2,2,4,4
            var sp: fx = 1fx - 0.3fx * (kk as fx) / 4fx;    // 层速 1.0/0.85/0.85/0.7/0.7
            var hb: int = ((q + 1) / 2) * 364;      // H(M,q)*2°（2°=364BAM）
            var base: int = alpha + hb;
            if q % 2 != 0 { base = alpha - hb; }    // 2866 (-1)^q
            sh_angle(0, base as angle, 0deg);
            sh_speed(0, sp, 0fx);
            sh_dist(0, (0fx - 4fx) * sp);           // ANIM 进入时 position -= 4*velocity（沿本弹角）
            sh_xform(0, D7_RAMP((target - sp) / 120fx));
            sh_fire(0);                             // 2877 etOn(0)
        }
    }
    // 2880 @TaikoDead2() delete()：主任务自然结束 = 敌静默退场
}

// ── 1912-1929 / 412 moveRand(60,0,0.6) 与 504 限位（复用 TH16 已核配方，参数按本卡）
// 限位 moveLimit(0,128,160,64)：x∈[-80,80]、y∈[96,160]；方向内区 x±40、y112..144。
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var spd: fx = 0fx;
    if k < 60 { spd = 0.6fx * ((60 - k) as fx) / 60fx; }
    var nx: fx = $self_x + self_fx(0) * spd;
    var ny: fx = $self_y + self_fx(1) * spd;
    if nx < -80fx { nx = -80fx; }
    if nx > 80fx { nx = 80fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

sub card_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -40fx {
        a = r / 3;
    } else if $self_x > 40fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}
